    try {
      Logging.instance.log(Level.warning, "BROADCASTING TRANSACTION - THIS WILL SPEND REAL FUNDS!");
      
      // Only broadcast if explicitly enabled and we're on testnet
      // This is intentionally commented out for safety
      // 
      // final confirmedTxData = await wallet.confirmSend(txData: txData);
      // return confirmedTxData.txid;
      
      throw Exception("Transaction broadcasting is disabled for safety in test environment");
    } catch (e) {
      Logging.instance.log(Level.error, "Failed to broadcast transaction: $e");
      rethrow;
    }
  }

  /// Checks if wallet has sufficient balance for testing
  Future<bool> hasMinimumBalanceForTesting(Wallet wallet, Amount minimumAmount) async {
    try {
      final balance = await wallet.balance;
      return balance.spendable >= minimumAmount;
    } catch (e) {
      Logging.instance.log(Level.error, "Failed to check wallet balance: $e");
      return false;
    }
  }

  /// Gets recommended test amount based on wallet balance
  Future<Amount?> getRecommendedTestAmount(Wallet wallet) async {
    try {
      final balance = await wallet.balance;
      
      if (balance.spendable <= Amount.zero) {
        return null;
      }

      // Use 1% of spendable balance or minimum coin amount, whichever is larger
      final onePercent = balance.spendable ~/ BigInt.from(100);
      final minCoinAmount = Amount(
        rawValue: BigInt.one,
        fractionDigits: wallet.cryptoCurrency.fractionDigits,
      );

      return onePercent > minCoinAmount ? Amount(
        rawValue: onePercent,
        fractionDigits: wallet.cryptoCurrency.fractionDigits,
      ) : minCoinAmount;
    } catch (e) {
      Logging.instance.log(Level.error, "Failed to calculate recommended test amount: $e");
      return null;
    }
  }
}